import json

def render(data):
    payload=json.dumps(data,allow_nan=False).replace('<','\\u003c').replace('>','\\u003e').replace('&','\\u0026')
    return TEMPLATE.replace('__PAYLOAD__',payload)

TEMPLATE='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Ink / Handwritten Number Reader</title><style>
:root{--paper:#f5f1e8;--ink:#272c33;--muted:#6e737b;--blue:#375bca;--line:#d9d6cd;--orange:#b55e34}*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font:15px/1.55 system-ui,sans-serif}.wrap{max-width:1240px;margin:auto;padding:28px 34px}header,footer{display:flex;justify-content:space-between;font-size:12px;padding-bottom:20px;border-bottom:1px solid var(--line)}.brand{font-weight:800;letter-spacing:.12em}.small,p{color:var(--muted)}.small{font-size:12px}.hero{display:grid;grid-template-columns:1.3fr 1fr;gap:60px;padding:40px 0 25px}.tag{text-transform:uppercase;font-size:11px;letter-spacing:.15em;font-weight:750;color:var(--blue)}h1{font-size:clamp(36px,5vw,60px);line-height:1.05;letter-spacing:-.05em;margin:14px 0 22px}h2{font-size:25px;letter-spacing:-.025em;line-height:1.2;margin:7px 0 14px}h3{font-size:15px;margin:10px 0}p{margin:8px 0}.note{padding:24px;background:#e9e7df;border-left:3px solid var(--blue);align-self:center}.cards{display:grid;grid-template-columns:repeat(4,1fr);gap:14px;margin:20px 0 25px}.card,.panel{background:#fffdf8;border:1px solid var(--line);border-radius:10px;padding:20px}.value{font-size:30px;color:var(--blue);margin:5px 0}.grid{display:grid;grid-template-columns:1fr 1fr;gap:22px}.panel{margin-bottom:22px;min-width:0}.controls{display:flex;align-items:end;gap:12px;flex-wrap:wrap;margin:16px 0}label{display:flex;flex-direction:column;gap:6px;color:var(--muted);font-size:12px}select,button{padding:9px 12px;border:1px solid #b8bcc6;border-radius:6px;background:white;font:inherit;color:var(--ink)}button{cursor:pointer}button.primary{background:var(--blue);color:white;border-color:var(--blue)}.reader{display:grid;grid-template-columns:220px 1fr;gap:22px;align-items:start}.digit-image{width:100%;height:auto;max-width:220px;background:#1d2533;display:block}.result{font-size:54px;line-height:1.1;color:var(--blue);font-weight:700;margin:8px 0}.pill{display:inline-block;padding:4px 9px;background:#e4eafc;color:#294fac;border-radius:5px;font-size:11px;font-weight:700}.pill.review{background:#f5e5da;color:#96502d}.prob{display:flex;align-items:center;gap:10px;font-size:12px;margin:5px 0}.prob>span{width:15px}.track{height:9px;background:#e4e5e8;flex:1}.track i{display:block;height:100%;background:var(--blue)}.prob b{font-weight:400;width:42px;text-align:right}canvas{display:block;width:220px;height:220px;background:white;border:1px dashed #9fa7b6;touch-action:none;cursor:crosshair}.gallery{display:grid;grid-template-columns:repeat(8,1fr);gap:12px}.tile{padding:8px;border:1px solid var(--line);background:white;border-radius:6px;cursor:pointer}.tile svg{width:100%;display:block}.tile span{display:block;font-size:10px;margin-top:5px}.number{display:flex;gap:8px;margin:15px 0}.number svg{width:20%;max-width:100px}.scroll{overflow:auto;max-height:340px}table{width:100%;border-collapse:collapse;font-size:12px;font-variant-numeric:tabular-nums}th,td{padding:9px 8px;text-align:left;border-bottom:1px solid var(--line)}th{font-weight:600;color:var(--muted)}#confusion td{text-align:center;padding:7px;min-width:28px}details{font-size:13px}summary{cursor:pointer;font-weight:700}li{color:var(--muted);margin:7px 0}a{color:var(--blue)}footer{border:0;border-top:1px solid var(--line);padding-top:18px;margin-top:20px}.notice{color:var(--orange);font-size:12px}@media(max-width:850px){.hero,.grid{grid-template-columns:1fr;gap:20px}.cards{grid-template-columns:repeat(2,1fr)}.gallery{grid-template-columns:repeat(4,1fr)}.wrap{padding:20px}.reader{grid-template-columns:180px 1fr}canvas{width:180px;height:180px}}
</style><div class="wrap"><header><span class="brand">INK / NUMBER READER</span><span class="small">Computer vision · Handwriting & uncertainty</span></header><section class="hero"><div><div class="tag">Read the digit. Keep the doubt.</div><h1>When handwriting<br>needs a second look.</h1><p>A compact image classifier reads handwritten digits. A separate calibration set decides whether to return one candidate, several, or a request for review.</p><p class="small">UCI Optical Digits · Official independent-writer test set · Runs in your browser</p></div><div class="note"><h3>A different writer is a different test.</h3><p>The official training and test files come from different people. The test file stays separate from model fitting, selection and calibration.</p><p class="small">The drawing pad and four-digit examples are experiments. This is not a complete document OCR system.</p></div></section><div id="cards" class="cards"></div>
<div class="grid"><section class="panel"><div class="tag">Inspect a real held-out image</div><h2>One digit, possible readings</h2><div class="controls"><label for="sample">Test example<select id="sample"></select></label><label for="mode">Review policy<select id="mode"><option value="standard">Standard digit policy</option><option value="four_digit">Cautious four-digit policy</option></select></label></div><div class="reader"><div id="sampleImage"></div><div><span id="sampleStatus" class="pill"></span><div id="sampleResult" class="result"></div><p id="sampleTruth" class="small"></p><p id="sampleSet" class="small"></p></div></div><div id="scores"></div><p class="small">Bars show model scores, not independently calibrated probabilities. One candidate is a suggestion, not a guarantee.</p></section>
<section class="panel"><div class="tag">Try your handwriting</div><h2>Draw a single digit</h2><p class="small">Draw one large centered digit using a mouse or touch. The browser processes your strokes locally.</p><div class="reader"><canvas id="pad" width="224" height="224" aria-label="Handwritten digit drawing pad"></canvas><div><span id="engineStatus" class="pill">Loading reader</span><div id="drawResult" class="result">—</div><p id="drawSet" class="small">Draw, then select Read digit.</p></div></div><div class="controls"><button id="read" class="primary">Read digit</button><button id="clear">Clear drawing</button></div><p class="notice">Drawing inputs differ from scanned dataset images. The benchmark accuracy and prediction-set coverage do not apply to this pad.</p><p class="small">Empty drawings are rejected. Cropping, centering and downsampling approximate the original preprocessing.</p></section></div>
<section class="panel"><div class="tag">A digit can be right while a number is wrong</div><h2>Read a four-digit number</h2><p class="small">These are synthetic groups of four isolated test images, with fixed known boundaries. No text detection or image segmentation is being claimed.</p><div class="controls"><label for="numberIndex">Synthetic example<select id="numberIndex"></select></label></div><div id="numberImages" class="number"></div><div id="numberRead" class="result"></div><p id="numberDetail"></p><div class="scroll"><table><thead><tr><th>Policy</th><th>Exact number match</th><th>Single-candidate numbers</th><th>Accuracy on those numbers</th><th>All true digits in sets</th></tr></thead><tbody id="numberStats"></tbody></table></div><p class="small">500 seeded groups sampled with replacement from the same test pool; they are not 500 independent documents. The cautious policy divides the nominal 5% error budget across four digits. Its theoretical interpretation requires exchangeability, which is not established across writers.</p></section>
<section class="panel"><div class="tag">Error analysis</div><h2>Explore difficult examples</h2><div class="controls"><label for="galleryFilter">Show examples<select id="galleryFilter"><option value="all">All selected examples</option><option value="wrong">Misread digits</option><option value="review">Needs review</option></select></label></div><p class="small">Up to three incorrect and three correct examples per digit, in source order. This gallery deliberately includes errors and is not a random sample. Select a tile to inspect it.</p><div id="gallery" class="gallery"></div></section>
<div class="grid"><section class="panel"><div class="tag">Which digits are confused?</div><h2>Test confusion matrix</h2><p class="small">Rows: dataset labels. Columns: top model predictions. Darker cells contain more examples.</p><div class="scroll"><table id="confusion"></table></div></section><section class="panel"><div class="tag">Stress and coverage</div><h2>What happens when the image shifts?</h2><div id="stress"></div><p class="small">A one-pixel right shift in the 8 × 8 grid drops the final column. It is a severe synthetic perturbation; model and cutoffs remain fixed.</p><div id="coverage"></div><p class="small">Prediction-set coverage measures whether the true digit appears among the candidates. It is different from top-prediction accuracy and from accuracy on single-candidate cases.</p></section></div>
<section class="panel"><details open><summary>Model selection, calibration and reproducibility</summary><div id="method"></div><table><thead><tr><th>Candidate</th><th>Validation accuracy</th><th>Validation log loss</th></tr></thead><tbody id="candidates"></tbody></table><ul><li>Pixel counts are divided by 16. Neural networks use one ReLU hidden layer and internal early stopping on a subset of training images. Logistic regression provides a simpler baseline.</li><li>Model selection uses validation accuracy, breaking ties by log loss. Calibration labels are used only after selection; the final test file is used only for evaluation.</li><li>Prediction sets use the finite-sample quantile of one minus the score assigned to the true digit. Marginal nominal coverage requires exchangeability; it is not guaranteed for new writers, each digit class, drawing inputs or arbitrary documents.</li><li>Internal partitions do not have writer identifiers. Writer-level uncertainty and correlated examples are not quantified. Exact duplicate pixels are audited across files.</li></ul><p><a href="metrics.json">Metrics & provenance</a> · <a href="model.json">Portable model</a> · <a href="predictions.csv">Test predictions</a> · <a href="splits.csv">Split manifest</a></p></details></section><footer><span>Ehsan Cheraghi · Handwritten Number Reader</span><span>Digit data: Alpaydin & Kaynak / UCI · <a href="https://doi.org/10.24432/C50P49">CC BY 4.0 source</a></span></footer></div>
<script>const D=__PAYLOAD__,S=D.summary,M=D.model,$=id=>document.getElementById(id),pct=x=>x===null?'—':(100*x).toFixed(1)+'%';
function infer(pixels){let a=pixels.map(x=>x/16);M.weights.forEach((w,l)=>{let b=M.biases[l].map((v,j)=>v+a.reduce((s,x,i)=>s+x*w[i][j],0));a=l<M.weights.length-1?b.map(x=>Math.max(0,x)):b});let mx=Math.max(...a),e=a.map(x=>Math.exp(x-mx)),total=e.reduce((a,b)=>a+b,0);return e.map(x=>x/total)}
function candidates(p,mode=$('mode').value){return p.map((x,i)=>x>=M.cutoffs[mode].minimum_score?i:-1).filter(x=>x>=0)}
function bestDigit(p){return p.indexOf(Math.max(...p))}const P=D.pixels.map(infer);
let maxError=0;D.checks.forEach(c=>c.scores.forEach((v,j)=>{maxError=Math.max(maxError,Math.abs(P[c.index][j]-v))}));$('engineStatus').textContent=maxError<1e-10?'Reader ready':'Reader unavailable';$('engineStatus').dataset.parity=maxError;
function svg(pixels,label='Digit image'){return '<svg class="digit-image" viewBox="0 0 8 8" role="img" aria-label="'+label+'">'+pixels.map((v,i)=>'<rect x="'+i%8+'" y="'+Math.floor(i/8)+'" width="1" height="1" fill="rgb('+Math.round(v/16*255)+','+Math.round(v/16*255)+','+Math.round(v/16*255)+')"/>').join('')+'</svg>'}
const card=(name,value,sub)=>'<div class="card"><span class="small">'+name+'</span><div class="value">'+value+'</div><span class="small">'+sub+'</span></div>';
const T=S.test.standard;$('cards').innerHTML=card('Digit accuracy',pct(T.accuracy),T.correct+' / '+T.n+' official test images')+card('Prediction-set coverage',pct(T.set_coverage),'Standard policy · measured on test')+card('Single-candidate accuracy',pct(T.singleton_accuracy),'Among '+T.singleton_count+' suggestions')+card('Needs review',pct(T.review_count/T.n),'Empty or multiple-candidate sets');
$('sample').innerHTML=D.examples.map(i=>'<option value="'+i+'">Test '+String(i).padStart(4,'0')+' · label '+D.labels[i]+'</option>').join('');
$('numberIndex').innerHTML=D.number_indices.map((v,i)=>'<option value="'+i+'">Number '+(i+1)+'</option>').join('');
function sample(){let i=+$('sample').value,p=P[i],set=candidates(p);$('sampleImage').innerHTML=svg(D.pixels[i]);$('sampleResult').textContent=bestDigit(p);$('sampleTruth').textContent='Dataset label: '+D.labels[i]+' · '+(bestDigit(p)===D.labels[i]?'Top prediction matches':'Top prediction is incorrect');$('sampleSet').textContent='Candidates: '+(set.length?set.join(', '):'none');$('sampleStatus').textContent=set.length===1?'Single candidate':'Needs review';$('sampleStatus').className='pill'+(set.length===1?'':' review');$('scores').innerHTML=p.map((v,j)=>'<div class="prob"><span>'+j+'</span><div class="track"><i style="width:'+pct(v)+'"></i></div><b>'+pct(v)+'</b></div>').join('')}
function number(){let ids=D.number_indices[+$('numberIndex').value],sets=ids.map(i=>candidates(P[i]));$('numberImages').innerHTML=ids.map(i=>svg(D.pixels[i])).join('');$('numberRead').textContent=ids.map(i=>bestDigit(P[i])).join('');$('numberDetail').textContent='Label: '+ids.map(i=>D.labels[i]).join('')+' · '+(sets.every(s=>s.length===1)?'Single-candidate number':'Needs review')+' · sets '+sets.map(s=>'{'+s.join(',')+'}').join(' ')}
function gallery(){let mode=$('galleryFilter').value,ids=D.examples.filter(i=>mode==='all'||(mode==='wrong'&&bestDigit(P[i])!==D.labels[i])||(mode==='review'&&candidates(P[i]).length!==1));$('gallery').innerHTML=ids.map(i=>'<button class="tile" data-index="'+i+'" aria-label="Inspect test '+i+'">'+svg(D.pixels[i])+'<span>Label '+D.labels[i]+' → read '+bestDigit(P[i])+'</span></button>').join('')||'<p>No examples match.</p>';document.querySelectorAll('.tile').forEach(el=>el.onclick=()=>{$('sample').value=el.dataset.index;sample();$('sample').focus()})}
$('sample').onchange=sample;$('mode').onchange=()=>{sample();number();gallery();if($('drawResult').textContent!=='—')readDrawing()};$('numberIndex').onchange=number;$('galleryFilter').onchange=gallery;
$('numberStats').innerHTML=Object.entries(S.numbers).map(([key,n])=>'<tr><td>'+key.replace('_',' ')+'</td><td>'+pct(n.exact_match)+'</td><td>'+n.read_count+' / '+n.count+'</td><td>'+pct(n.read_accuracy)+'</td><td>'+pct(n.whole_set_coverage)+'</td></tr>').join('');
let c=T.confusion;$('confusion').innerHTML='<thead><tr><th>Label</th>'+Array.from({length:10},(_,i)=>'<th>'+i+'</th>').join('')+'</tr></thead><tbody>'+c.map((row,i)=>'<tr><th>'+i+'</th>'+row.map(v=>'<td style="background:rgba(55,91,202,'+(v/Math.max(...row)*.45)+')">'+v+'</td>').join('')+'</tr>').join('')+'</tbody>';
let shift=S.stress_right_shift;$('stress').innerHTML='<p>Original accuracy: <b>'+pct(T.accuracy)+'</b></p><p>Shifted accuracy: <b>'+pct(shift.accuracy)+'</b></p><p>Shifted review rate: <b>'+pct(shift.review_count/shift.n)+'</b></p>';$('coverage').innerHTML='<p>Standard set coverage: <b>'+pct(T.set_coverage)+'</b></p><p>Shifted set coverage: <b>'+pct(shift.set_coverage)+'</b></p><p class="notice">A review rule can still be confidently wrong under image shift.</p>';
$('method').innerHTML='<p class="small">Selected: '+S.selected+'. Development file: '+S.splits.train+' fit / '+S.splits.validation+' validation / '+S.splits.calibration+' calibration. Official test: '+S.splits.test+' images. Seed 42.</p>';$('candidates').innerHTML=S.selection.map(r=>'<tr><td>'+r.name+'</td><td>'+pct(r.validation_accuracy)+'</td><td>'+r.validation_log_loss.toFixed(4)+'</td></tr>').join('');
const pad=$('pad'),ctx=pad.getContext('2d');let drawing=false;function clear(){ctx.fillStyle='white';ctx.fillRect(0,0,224,224);$('drawResult').textContent='—';$('drawSet').textContent='Draw, then select Read digit.'}clear();function pos(e){let r=pad.getBoundingClientRect();return[(e.clientX-r.left)*224/r.width,(e.clientY-r.top)*224/r.height]}
pad.onpointerdown=e=>{drawing=true;pad.setPointerCapture(e.pointerId);ctx.strokeStyle='black';ctx.fillStyle='black';ctx.lineWidth=17;ctx.lineCap='round';ctx.lineJoin='round';let [x,y]=pos(e);ctx.beginPath();ctx.arc(x,y,8.5,0,2*Math.PI);ctx.fill();ctx.beginPath();ctx.moveTo(x,y)};pad.onpointermove=e=>{if(drawing){ctx.lineTo(...pos(e));ctx.stroke()}};pad.onpointerup=()=>drawing=false;pad.onpointercancel=()=>drawing=false;$('clear').onclick=clear;
function readDrawing(){const a=ctx.getImageData(0,0,224,224).data;let x0=224,y0=224,x1=-1,y1=-1,ink=0;for(let y=0;y<224;y++)for(let x=0;x<224;x++){if(a[(y*224+x)*4]<200){x0=Math.min(x0,x);x1=Math.max(x1,x);y0=Math.min(y0,y);y1=Math.max(y1,y);ink++}}if(ink<30){$('drawResult').textContent='—';$('drawSet').textContent='No digit detected. Draw a larger digit.';return}let temp=document.createElement('canvas');temp.width=temp.height=32;let t=temp.getContext('2d');t.fillStyle='white';t.fillRect(0,0,32,32);let w=x1-x0+1,h=y1-y0+1,scale=28/Math.max(w,h),dw=w*scale,dh=h*scale;t.drawImage(pad,x0,y0,w,h,(32-dw)/2,(32-dh)/2,dw,dh);let b=t.getImageData(0,0,32,32).data,pixels=[];for(let y=0;y<8;y++)for(let x=0;x<8;x++){let count=0;for(let dy=0;dy<4;dy++)for(let dx=0;dx<4;dx++)count+=1-b[((4*y+dy)*32+4*x+dx)*4]/255;pixels.push(count)}let p=infer(pixels),set=candidates(p);$('drawResult').textContent=bestDigit(p);$('drawSet').textContent='Experimental candidates: '+(set.length?set.join(', '):'none — review')+'. Drawing accuracy is unmeasured.'}
$('read').onclick=()=>{if(maxError<1e-10)readDrawing()};sample();number();gallery();</script></html>'''
